# 因式分解（題目卷＋解析卷）
F=[
(r'因式分解 \(2x^2+3x=\)？',[r'\(2(x^2+3)\)',r'\(x(2x+3)\)',r'\(x^2+x^2+x\)',r'\(2(x^2+1)\)'],'B',r'\(2x^2+3x=x(2x+3)\)',None),
(r'A、B 為 x 的多項式，設 \(A=2x+3\)，\(B=(2x+3)(3x-1)\)，則下列何者「錯誤」？',['A 是 B 的因式','B 是 A 的倍式','B 除以 A 的餘式為零',r'\(1-3x\) 不能整除 B'],'D',r'(D) \(B\div(1-3x)=-(2x+3)\)，所以 \(1-3x\) 可以整除 B，這個敘述錯誤。',None),
(r'設 x、y 均為實數，且 \(x^2+y^2-8y+16=0\)，則 \(3x+2y=\)？',['12','8','4','0'],'B',r'\(x^2+y^2-8y+16=0\Rightarrow x^2+(y-4)^2=0\)\n所以 \(x=0\)，\(y=4\)，\(3x+2y=3\times0+2\times4=8\)。',None),
(r'若 \((x^2-9x+5)-A=-2x^2+9x+26\)，則下列何者是 A 的因式？',[r'\(x^2+x+1\)',r'\(x-1\)',r'\(x+1\)',r'\(x+7\)'],'C',r'\(A=x^2-9x+5-(-2x^2+9x+26)=3x^2-18x-21=3(x^2-6x-7)=3(x-7)(x+1)\)',None),
(r'若 \(2x^3+3x^2-8x-12=(x+2)(x-2)(2x+3)\)，則下列何者「不是」\(2x^3+3x^2-8x-12\) 的因式？',[r'\(5(2x+3)\)',r'\(x^2+2\)',r'\(x^2-4\)',r'\(2x^3+3x^2-8x-12\)'],'B',r'因式可以是本身，以及 \((x+2)\)、\((x-2)\)、\((2x+3)\) 的乘積（可乘上常數），例如 \((x+2)(x-2)=x^2-4\)。\n\(x^2+2\) 不是它的因式。',None),
(r'已知 \(2x-y=5\)，則 \(4x^2-4xy+y^2-6x+3y+7\) 的值為多少？',['2','6','17','25'],'C',r'\(=(4x^2-4xy+y^2)-3(2x-y)+7=(2x-y)^2-3(2x-y)+7=5^2-3\times5+7=17\)',None),
(r'若 \(2x^2+ax-18\) 可分解成 \((2x+b)(x-6)\)，則下列何者正確？',[r'\(a=15\)，\(b=-3\)',r'\(a=-9\)，\(b=3\)',r'\(a=-15\)，\(b=-3\)',r'\(a=9\)，\(b=3\)'],'B',r'\((2x+b)(x-6)=2x^2+(b-12)x-6b\)\n\(-6b=-18\Rightarrow b=3\)，\(a=b-12=-9\)。',None),
(r'若 \(14x^2+ax+1\) 可以用十字交乘法分解成兩個一次式的乘積，則下列何者「不可能」是 a 的值？',['15','9','−13','−9'],'C',r'(A) \(a=15\)：\(14x^2+15x+1=(14x+1)(x+1)\)\n(B) \(a=9\)：\(14x^2+9x+1=(7x+1)(2x+1)\)\n(D) \(a=-9\)：\(14x^2-9x+1=(7x-1)(2x-1)\)\n−13 無法分解。',None),
(r'因式分解 \(1-a^2-b^2+a^2b^2=\)？',[r'\((1-a^2)(1+b^2)\)',r'\((1+a^2)(1-b^2)\)',r'\((1+a)(1-a)(1+b)(1-b)\)',r'\((1+a)(1-a)(1+b^2)\)'],'C',r'原式 \(=(1-a^2)-(b^2-a^2b^2)=(1-a^2)-b^2(1-a^2)=(1-a^2)(1-b^2)=(1+a)(1-a)(1+b)(1-b)\)',None),
(r'下列何者是 \(6x^2-10x\) 與 \(9x^2-25\) 的公因式？',['x',r'\(3x-5\)',r'\(3x+5\)',r'\(x^2\)'],'B',r'\(6x^2-10x=2x(3x-5)\)，\(9x^2-25=(3x+5)(3x-5)\)，公因式為 \(3x-5\)。',None),
(r'若 \(x+2\) 與 \(x-3\) 皆為 \(x^3+mx^2+nx-6\) 的因式，則 \(m+n=\)？',['7','−7','6','−6'],'B',r'\((x+2)(x-3)=x^2-x-6\) 也是 \(x^3+mx^2+nx-6\) 的因式。\n用長除法：\(x^3+mx^2+nx-6\) 除以 \(x^2-x-6\)，商為 \(x+1\)，要整除需 \(m+1=1\)、\(n+6=-1\)。\n得 \(m=0\)，\(n=-7\)，\(m+n=-7\)。',None),
(r'下列哪一個多項式「不是」\(x(1+x-y^2)-y(1+y-x^2)\) 的因式？',[r'\(x-y\)',r'\(x+y\)',r'\(x+1\)',r'\(y+1\)'],'B',r'原式 \(=x+x^2-xy^2-y-y^2+x^2y=(x^2y-xy^2)+(x^2-y^2)+(x-y)\)\n\(=(x-y)(xy+x+y+1)=(x-y)(x+1)(y+1)\)，\(x+y\) 不是因式。',None),
(r'下列何者「不是」多項式 \((x-1)(x+1)\) 的因式？',[r'\(x+1\)',r'\(x-1\)',r'\((x-1)(x+1)\)',r'\((x+1)^2\)'],'D',r'\((x-1)(x+1)\) 的因式有 \(1\)、\(x+1\)、\(x-1\)、\((x-1)(x+1)\)（以及它們的常數倍），\((x+1)^2\) 不是。',None),
(r'下列何者為多項式 \((x+5)(x-3)\) 與 \((x-3)(x-5)\) 的公因式？',[r'\(x+5\)',r'\(x-5\)',r'\(x-3\)',r'\((x-5)(x-1)\)'],'C',r'兩個多項式都含有 \((x-3)\)，所以公因式是 \(x-3\)。',None),
(r'若 \(x^2-5x+4=(x+a)(x+b)\)，且 \(a>b\)，則 \(a=\)？',['1','4','−1','−4'],'C',r'十字交乘：\(x^2-5x+4=(x-1)(x-4)\)。\n因為 \(a>b\)，所以 \(a=-1\)，\(b=-4\)。',None),
(r'因式分解 \((x-1)(7x-3)-(1-x^2)=\)？',[r'\(2(x-1)(4x-1)\)',r'\((x-1)(4x-1)\)',r'\(2(x-1)(3x-2)\)',r'\((x-1)(3x-2)\)'],'A',r'原式 \(=(x-1)(7x-3)-(1+x)(1-x)=(x-1)(7x-3)+(1+x)(x-1)\)\n\(=(x-1)(7x-3+1+x)=(x-1)(8x-2)=2(x-1)(4x-1)\)',None),
(r'下列何者「不是」\(x^2(y-z)+y^2(z-y)\) 的因式？',[r'\(x^2+y^2\)',r'\(x^2-y^2\)',r'\(y-z\)',r'\(x+y\)'],'A',r'原式 \(=x^2(y-z)-y^2(y-z)=(y-z)(x^2-y^2)=(y-z)(x+y)(x-y)\)，\(x^2+y^2\) 不是因式。',None),
(r'下列何者是 \(c(a^2-b^2)-a(b^2-c^2)\) 的因式？',[r'\(a-c\)',r'\(a+c\)',r'\(a^2-bc\)',r'\(b^2+ac\)'],'B',r'原式 \(=a^2c-b^2c-ab^2+ac^2=(a^2c+ac^2)-(b^2c+ab^2)=ac(a+c)-b^2(a+c)=(a+c)(ac-b^2)\)',None),
(r'如圖，甲、乙、丙、丁四個長方形可以拼成一個大長方形 ABCD，若甲、乙、丙、丁的面積分別是 \(x^2\)、\(ax\)、\(bx\)、\(ab\)，且 a、b、x 皆為正數，則此長方形的面積可以表示成下列何者？',[r'\((a+x)(b+x)\)',r'\((a+b)(a+x)\)',r'\((a+b)(b+x)\)',r'\((x+b)(x+ab)\)'],'A',r'長方形面積 \(=x^2+ax+bx+ab=(x^2+ax)+(bx+ab)=x(x+a)+b(x+a)=(x+a)(x+b)\)','F19'),
(r'有兩個多項式 \(3x^2+7x+4\) 與 \(9x^2+24x+16\)，則這兩個多項式的公因式為何？',[r'\(x+1\)',r'\(3x+4\)',r'\(3x+2\)',r'\(x+4\)'],'B',r'\(3x^2+7x+4=(3x+4)(x+1)\)，\(9x^2+24x+16=(3x+4)^2\)，公因式為 \(3x+4\)。',None),
(r'若 \(x^2-2x-15=(x+a)(x+b)\)，且 \(a>b\)，則 \(a=\)？',['−5','5','3','−3'],'C',r'十字交乘：\(x^2-2x-15=(x-5)(x+3)\)。因為 \(a>b\)，所以 \(a=3\)。',None),
(r'已知 \(3x^2-21x-24=3(x+1)(x-8)\)，則下列何者是 \(3x^2-21x-24\) 的因式？',[r'\(x-1\)',r'\(x+8\)',r'\(3x+3\)',r'\(3x-8\)'],'C',r'因式可以是 \(x+1\)、\(x-8\) 及它們的常數倍與乘積，\(3x+3=3(x+1)\) 是因式。',None),
(r'下列何者為 \((x-y)(x-y-5)-24\) 的因式？',[r'\(x-y-2\)',r'\(x-y-3\)',r'\(x-y-6\)',r'\(x-y-8\)'],'D',r'設 \(x-y=a\)，原式 \(=a(a-5)-24=a^2-5a-24=(a+3)(a-8)=(x-y+3)(x-y-8)\)',None),
(r'多項式 \(33x^2-x-14\) 可因式分解成 \((3x-a)(bx+c)\)，其中 a、b、c 均為整數，求 \(a+b+c\) 的值為何？',['16','20','23','43'],'B',r'\(33x^2-x-14=(3x-2)(11x+7)\)，所以 \(a=2\)，\(b=11\)，\(c=7\)，\(a+b+c=20\)。',None),
(r'利用因式分解 \(9x^4-37x^2+4\) 的結果，將 \(9\times31^4-37\times31^2+4\) 寫成標準分解式，則下列何者正確？',[r'\(2^2\times3\times11\times23\times29\times47\)',r'\(2^3\times3\times13\times23\)',r'\(2^2\times3\times13\times23\times29\times47\)',r'\(2^3\times3\times11\times23\times29\times47\)'],'D',r'\(9x^4-37x^2+4=(9x^2-1)(x^2-4)=(3x+1)(3x-1)(x+2)(x-2)\)\n代入 \(x=31\)：\((94)(92)(33)(29)=2\times47\times2^2\times23\times3\times11\times29=2^3\times3\times11\times23\times29\times47\)',None),
]
